// Paste the Slack incoming-webhook URL for the channel these should land in.
// No Slack credential needed - a webhook is all it takes.
const SLACK_WEBHOOK = '';
// Counts only - no client names, no content. Healthy = the schedules ran in
// the last 24h and nothing is stuck mid-pipeline.
const r = $input.first().json;
const healthy = Number(r.runs_24h) > 0 && Number(r.stuck) === 0;
const line = healthy
  ? `\u2705 TN Brain healthy \u00b7 ${r.calls_24h} call(s) ingested and ${r.signals_24h} signal(s) extracted in the last 24h \u00b7 latest call ${r.latest_call}`
  : `\u26a0\ufe0f TN Brain needs a look \u00b7 runs in last 24h: ${r.runs_24h} \u00b7 stuck items: ${r.stuck} \u00b7 failed items: ${r.failed} \u00b7 latest call ${r.latest_call}`;
// Dead-man's switch: paste a healthchecks.io ping URL here. If this heartbeat
// ever stops arriving, Bilawal gets an email - without any data leaving.
const PING_URL = '';
return [{ json: { webhook: SLACK_WEBHOOK, line, healthy, ping: PING_URL ? (healthy ? PING_URL : PING_URL + '/fail') : null } }];
